   #define DEF_ADDRS_PER_INODE(sbi)    ((sbi)->addrs_per_inode)
   #define DEF_ADDRS_PER_BLOCK(sbi)    ((sbi)->addrs_per_block)
   #define NIDS_PER_BLOCK(sbi)         ((sbi)->nids_per_block)

