+	vma = _install_special_mapping(mm, area, PAGE_SIZE,
+			VM_READ|VM_EXEC|VM_MAYEXEC|VM_MAYREAD|VM_IO,
+			&ptwrite_mapping);
+	if (IS_ERR(vma)) {
+		__free_page(ptw->page);
+		kfree(ptw);
+		return NULL;
+	}
